public static byte[] PadLeft(this ReadOnlySpan<byte> bytes, int length, byte padding = 0)
{
    if (bytes.Length == length)
    {
        return bytes.ToArray();
    }

    if (bytes.Length > length)
    {
        return bytes[..length].ToArray();
    }

    byte[] result = new byte[length];
